<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from "vue";
import { RouterLink } from "vue-router";
import { storeToRefs } from "pinia";
import { useEventStore } from "@/stores/events";
import EventCard from "@/components/EventCard.vue";
import SkeletonLoader from "@/components/SkeletonLoader.vue";
const eventStore=useEventStore(); const {featuredEvents,error}=storeToRefs(eventStore); const loadingFeatured=ref(true);
const sortedFeaturedEvents=computed(()=>[...(featuredEvents.value||[])].sort((a,b)=>Number(b.id||0)-Number(a.id||0)).slice(0,6));
const setMeta=(selector,attribute,value)=>{let element=document.head.querySelector(selector);if(!element){element=document.createElement("meta");const match=selector.match(/(?:property|name)="([^"]+)"/);if(match)element.setAttribute(selector.includes("property=")?"property":"name",match[1]);document.head.appendChild(element)}element.setAttribute(attribute,value)};
const applyLandingSeo=()=>{const title="KakaTickets | Find Events & Sell Tickets in Nigeria";const description="Find events, buy tickets, create events and sell tickets with KakaTickets. See ticket sales, share event links, message attendees and check guests in.";const canonicalUrl=`${window.location.origin}/`;document.title=title;setMeta('meta[name="description"]',"content",description);setMeta('meta[property="og:title"]',"content",title);setMeta('meta[property="og:description"]',"content",description);setMeta('meta[property="og:type"]',"content","website");setMeta('meta[property="og:url"]',"content",canonicalUrl);setMeta('meta[name="twitter:title"]',"content",title);setMeta('meta[name="twitter:description"]',"content",description);let canonical=document.head.querySelector('link[rel="canonical"]');if(!canonical){canonical=document.createElement("link");canonical.rel="canonical";document.head.appendChild(canonical)}canonical.href=canonicalUrl;document.getElementById("kakatickets-home-schema")?.remove();const schema=document.createElement("script");schema.id="kakatickets-home-schema";schema.type="application/ld+json";schema.textContent=JSON.stringify({"@context":"https://schema.org","@graph":[{"@type":"WebSite","@id":`${canonicalUrl}#website`,name:"KakaTickets",url:canonicalUrl,inLanguage:"en-NG",potentialAction:{"@type":"SearchAction",target:`${window.location.origin}/search?q={search_term_string}`,"query-input":"required name=search_term_string"}},{"@type":"Organization","@id":`${canonicalUrl}#organization`,name:"KakaTickets",url:canonicalUrl}]});document.head.appendChild(schema)};
onMounted(async()=>{applyLandingSeo();try{await eventStore.fetchFeaturedEvents()}catch(err){console.error("Unable to load featured events",err)}finally{loadingFeatured.value=false}});onBeforeUnmount(()=>document.getElementById("kakatickets-home-schema")?.remove());
</script>
<template><div class="home-page"><section class="events-section" aria-labelledby="featured-events-title"><div class="landing-shell"><div class="section-heading"><div><p class="section-kicker">Go somewhere</p><h2 id="featured-events-title">Events worth leaving the house for.</h2></div><RouterLink to="/search" class="text-link">See all events <span>→</span></RouterLink></div><div v-if="loadingFeatured&&!sortedFeaturedEvents.length" class="featured-skeleton"><SkeletonLoader type="grid" :count="4"/></div><div v-else-if="error&&!sortedFeaturedEvents.length" class="simple-state" role="status"><strong>Events could not load.</strong><button type="button" @click="eventStore.fetchFeaturedEvents()">Try again</button></div><div v-else-if="!sortedFeaturedEvents.length" class="simple-state"><strong>Nothing featured right now.</strong><span>Browse all events to see what is available.</span></div><div v-else class="event-grid"><EventCard v-for="event in sortedFeaturedEvents" :key="event.id" :event="event"/></div></div></section><section class="organiser-intro" aria-labelledby="organiser-title"><div class="landing-shell organiser-intro-grid"><div><p class="section-kicker">For organisers</p><h2 id="organiser-title">Sell tickets. Know what is happening.</h2></div><div class="organiser-intro-copy"><p>Create your event, share it, see what is selling, talk to your guests and get people through the door.</p><RouterLink to="/create-event" class="primary-link">Create an event <span>→</span></RouterLink></div></div></section><section class="feature-stories" aria-label="KakaTickets organiser features">
<article class="feature-story"><div class="landing-shell feature-grid"><div class="feature-copy"><span>01</span><p class="section-kicker">Sales</p><h2>Watch sales come in.</h2><p>See how many tickets sold, how much you made and what still needs to sell.</p></div><div class="product-frame"><div class="mini-titlebar"><div><span>Event overview</span><strong>Comedy Meets Dance</strong></div><em>Live</em></div><div class="metric-grid"><div><span>Tickets sold</span><strong>612</strong><small>612 of 850</small></div><div><span>Revenue</span><strong>₦7.4M</strong><small>₦1.2M this week</small></div><div><span>Spots left</span><strong>238</strong><small>out of 850</small></div><div><span>Page views</span><strong>4,821</strong><small>3.2% buy a ticket</small></div></div><div class="app-card"><b>Ticket performance</b><p>Gold Table <i style="width:93%"/> 93%</p><p>VIP <i style="width:76%"/> 76%</p><p>General Admission <i style="width:35%"/> 35%</p></div></div></div></article>
<article class="feature-story"><div class="landing-shell feature-grid feature-grid--reverse"><div class="feature-copy"><span>02</span><p class="section-kicker">Buyer sources</p><h2>Know where buyers found you.</h2><p>See which links are bringing buyers, so you know where to share next.</p></div><div class="product-frame"><div class="mini-titlebar"><div><span>Top buyer channels</span><strong>Where buyers came from</strong></div><small>Purchases by source</small></div><div class="app-card"><p><b>WA WhatsApp</b> 271 buyers <i style="width:44%"/> 44%</p><p><b>↗ Direct link</b> 148 buyers <i style="width:24%"/> 24%</p><p><b>IG Instagram</b> 110 buyers <i style="width:18%"/> 18%</p></div><div class="source-note"><span>Next move</span><strong>Share the offer on WhatsApp.</strong><small>This is already where most buyers are coming from.</small></div></div></div></article>
<article class="feature-story"><div class="landing-shell feature-grid"><div class="feature-copy"><span>03</span><p class="section-kicker">Promos</p><h2>Move the tickets that need help.</h2><p>Create a simple discount code, then share it where your buyers already are.</p></div><div class="product-frame"><div class="mini-titlebar"><div><span>Promo codes</span><strong>Your discounts</strong></div><button type="button" tabindex="-1">+ New code</button></div><div class="metric-grid three"><div><span>Active codes</span><strong>3</strong></div><div><span>Total uses</span><strong>87</strong></div><div><span>Revenue from codes</span><strong>₦620K</strong></div></div><div class="app-card"><p><b>LASVIP30</b> 30% off VIP tickets <small>42 uses</small></p><p><b>FRIENDS</b> ₦2,000 off any ticket <small>29 uses</small></p><p><b>MEDIA50</b> Free ticket <small>16 uses</small></p></div></div></div></article>
<article class="feature-story"><div class="landing-shell feature-grid feature-grid--reverse"><div class="feature-copy"><span>04</span><p class="section-kicker">Messages</p><h2>Tell everyone at once.</h2><p>Send one clear update to everyone who bought a ticket.</p></div><div class="product-frame"><div class="mini-titlebar"><div><span>Message attendees</span><strong>Send a message</strong></div><small>612 ticket holders</small></div><div class="compose"><p>To <b>All attendees (612)</b></p><p>Subject <strong>Quick update about Comedy Meets Dance</strong></p><div>Hey everyone!<br><br>Doors open at 5:30 PM, 30 minutes before the show starts. Come early to grab your spot.<br><br>Free parking is available through the main gate.</div><button type="button" tabindex="-1">Send to 612 people</button></div><div class="source-note"><span>Past email</span><strong>VIP spots almost gone</strong><small>71% opened · 31% clicked</small></div></div></div></article>
<article class="feature-story"><div class="landing-shell feature-grid"><div class="feature-copy"><span>05</span><p class="section-kicker">At the door</p><h2>Get people in quickly.</h2><p>Scan ticket QR codes or search a guest by name when they arrive.</p></div><div class="product-frame"><div class="mini-titlebar"><div><span>Door check-in</span><strong>Who’s here?</strong></div><small>612 tickets sold</small></div><div class="metric-grid three"><div><span>Checked in</span><strong class="teal">312</strong></div><div><span>Not yet arrived</span><strong>300</strong></div><div><span>Check-in rate</span><strong>51%</strong></div></div><div class="checkin"><div class="qr">▦<strong>Event QR code</strong><small>Scan tickets at the entrance.</small></div><div class="app-card"><p>Search by name or ticket number…</p><p><b>AO Adaeze Okonkwo</b> VIP · #8821 <em>In</em></p><p><b>CA Chioma Adekunle</b> Early Bird · #8823 <em>Waiting</em></p><p><b>EI Emeka Ifeanyi</b> VIP · #8825 <em>Waiting</em></p></div></div></div></div></article>
<article class="feature-story"><div class="landing-shell feature-grid feature-grid--reverse"><div class="feature-copy"><span>06</span><p class="section-kicker">Earnings</p><h2>See your money clearly.</h2><p>See ticket money, fees and what is ready to withdraw.</p></div><div class="product-frame"><div class="payout"><span>Available to withdraw</span><strong>₦7,415,000</strong><small>After 5% platform fee · ₦390,263 deducted</small><button type="button" tabindex="-1">Withdraw now</button></div><div class="app-card"><b>Transactions</b><p>4 tickets sold — General, VIP <em>+₦50,000</em></p><p>2 tickets sold — Early Bird <em>+₦10,000</em></p><p>Platform fee <em>-₦500</em></p><p>1 Gold Table sold <em>+₦250,000</em></p></div></div></div></article></section><section class="final-cta"><div class="landing-shell final-cta-inner"><div><p class="section-kicker">Ready when you are</p><h2>Your event. Your tickets. One simple place.</h2></div><RouterLink to="/create-event">Create an event <span>→</span></RouterLink></div></section></div></template>
<style scoped>
