ng:.16em}.feature-copy h2{font-size:clamp(2.5rem,4.5vw,4.75rem);line-height:.98}.product-frame{padding:clamp(15px,2vw,24px);border:1px solid var(--color-border);border-radius:24px;background:var(--color-surface);box-shadow:var(--shadow-elevated)}.mini-titlebar{align-items:center;padding-bottom:17px;border-bottom:1px solid var(--color-border)}.mini-titlebar div{display:grid;gap:4px}.mini-titlebar span,.mini-titlebar small,small{color:var(--color-muted);font-size:.7rem}.mini-titlebar strong{font-size:.92rem}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;padding:17px 0}.metric-grid>div,.source-note,.payout{padding:14px;border-radius:15px;background:var(--color-tab-bg)}.metric-grid span,.metric-grid small{display:block;color:var(--color-muted);font-size:.65rem}.metric-grid strong{display:block;margin:7px 0 4px;font-size:clamp(1.02rem,2vw,1.55rem)}.teal,em{color:#29b89a}.three{grid-template-columns:repeat(3,1fr)}.app-card,.compose{margin-top:12px;overflow:hidden;border:1px solid var(--color-border);border-radius:16px}.app-card>b,.app-card p,.compose p,.compose div{display:block;margin:0;padding:13px 14px;border-bottom:1px solid var(--color-border);font-size:.72rem}.app-card i{display:inline-block;width:35%;height:5px;margin:0 8px;background:var(--color-accent);border-radius:9px}.app-card small,.app-card em{float:right}.source-note{margin-top:14px;display:grid;gap:4px}.compose div{min-height:135px;line-height:1.55}.compose button{float:right;margin:10px}.checkin{display:grid;grid-template-columns:.72fr 1.28fr;gap:10px}.qr{display:grid;place-items:center;padding:18px;border:1px solid var(--color-border);border-radius:16px;font-size:5rem}.qr strong,.qr small{font-size:.73rem}.payout strong,.payout span,.payout small{display:block}.payout strong{font-size:clamp(2rem,5vw,3.6rem)}.final-cta{background:var(--color-surface)}.final-cta h2{font-size:clamp(2.5rem,5.1vw,5rem);line-height:.98}.final-cta a{padding:15px 20px;border-radius:999px;background:var(--color-accent);color:#fff;text-decoration:none;font-weight:750}@media(max-width:980px){.organiser-intro-grid,.feature-grid{grid-template-columns:1fr}.feature-grid--reverse .feature-copy,.feature-grid--reverse .product-frame{grid-column:auto;grid-row:auto}}@media(max-width:760px){.landing-shell{width:min(100% - 28px,1320px)}.section-heading,.final-cta-inner{align-items:flex-start;flex-direction:column}.event-grid{grid-template-columns:1fr}.metric-grid{grid-template-columns:repeat(2,1fr)}.three{grid-template-columns:repeat(3,1fr)}}@media(max-width:560px){.product-frame{padding:12px;border-radius:18px}.checkin{grid-template-columns:1fr}.qr{font-size:3rem}}
